const listStoriedChildren = `-- name: ListStoriedChildren :many
SELECT p.id, p.kind, p.name, p.parent_id, p.timezone, p.source, p.user_added,
       coalesce(p.category, '')::text AS category
FROM (
    SELECT CASE WHEN $1::uuid IS NULL THEN a.place_path[1]
                ELSE a.place_path[array_position(a.place_path, $1::uuid) + 1] END AS child_id,
           max(a.created_at) AS latest
    FROM arcs a
    WHERE ($1::uuid IS NULL OR a.place_path @> ARRAY[$1::uuid])
      AND NOT EXISTS (SELECT 1 FROM places h WHERE h.id = ANY(a.place_path) AND h.hidden_at IS NOT NULL)
      AND EXISTS (SELECT 1 FROM perspectives v
                  WHERE v.arc_id = a.id AND v.status = 'PERSPECTIVE_STATUS_PUBLISHED'
                    AND v.deleted_at IS NULL AND v.hidden_at IS NULL)
    GROUP BY 1
) t
JOIN places p ON p.id = t.child_id
ORDER BY t.latest DESC, p.id
LIMIT $2::integer
`

type ListStoriedChildrenParams struct {
	ParentID uuid.NullUUID
	Lim      int32
}

type ListStoriedChildrenRow struct {
	ID        uuid.UUID
	Kind      string
	Name      string
	ParentID  uuid.NullUUID
	Timezone  string
	Source    string
	UserAdded bool
	Category  string
}

// category is ” for a place with none.
// The children of a parent (the states when parent_id is NULL) with at least
// one readable story at or below them, most recently started arc first.
// Found from the arcs' place paths, so a state with a million places costs
// what its arcs cost.
func (q *Queries) ListStoriedChildren(ctx context.Context, arg ListStoriedChildrenParams) ([]ListStoriedChildrenRow, error) {
	rows, err := q.db.Query(ctx, listStoriedChildren, arg.ParentID, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListStoriedChildrenRow
	for rows.Next() {
		var i ListStoriedChildrenRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.Name,
			&i.ParentID,
			&i.Timezone,
			&i.Source,
			&i.UserAdded,
			&i.Category,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockVisibleParent = `-- name: LockVisibleParent :one
SELECT p.kind, p.timezone
FROM places p
WHERE p.id = $1::uuid AND p.hidden_at IS NULL
FOR SHARE
`

type LockVisibleParentRow struct {
	Kind     string
	Timezone string
}

// Holds the parent row against a concurrent hide until the insert commits.
func (q *Queries) LockVisibleParent(ctx context.Context, id uuid.UUID) (LockVisibleParentRow, error) {
	row := q.db.QueryRow(ctx, lockVisibleParent, id)
	var i LockVisibleParentRow
	err := row.Scan(&i.Kind, &i.Timezone)
	return i, err
}

const searchPlaces = `-- name: SearchPlaces :many
WITH RECURSIVE scope AS (
    SELECT p.id, 0 AS depth
    FROM places p
    WHERE p.id = $2::uuid AND p.hidden_at IS NULL
    UNION ALL
    SELECT ch.id, s.depth + 1
    FROM places ch
    JOIN scope s ON ch.parent_id = s.id
    WHERE ch.hidden_at IS NULL AND s.depth < 8
),
candidates AS (
    SELECT p.id, p.kind, p.name, p.parent_id, p.timezone, p.source, p.user_added,
           (lower(p.name) = $3::text) AS is_exact,
           (lower(p.name) LIKE $4::text) AS is_prefix,
           array_position(ARRAY['PLACE_KIND_STATE', 'PLACE_KIND_CITY', 'PLACE_KIND_TOWN',
                                'PLACE_KIND_MALL', 'PLACE_KIND_STORE']::text[], p.kind) AS level
    FROM places p
    WHERE p.hidden_at IS NULL
      AND lower(p.name) LIKE $5::text
      AND ($6::text IS NULL OR p.kind = $6::text)
      AND ($2::uuid IS NULL
           OR p.id IN (SELECT scope.id FROM scope WHERE scope.depth > 0))
    ORDER BY is_exact DESC, is_prefix DESC, level, char_length(p.name), lower(p.name), p.id
    LIMIT $7::integer
),
up AS (
    SELECT m.id AS place_id, m.parent_id AS ancestor_id, 1 AS depth
    FROM candidates m
    WHERE m.parent_id IS NOT NULL
    UNION ALL
    SELECT u.place_id, a.parent_id, u.depth + 1
    FROM up u
    JOIN places a ON a.id = u.ancestor_id
    WHERE a.parent_id IS NOT NULL AND u.depth < 8
)
SELECT m.id, m.kind, m.name, m.parent_id, m.timezone, m.source, m.user_added
FROM candidates m
WHERE NOT EXISTS (
    SELECT 1 FROM up u JOIN places a ON a.id = u.ancestor_id
    WHERE u.place_id = m.id AND a.hidden_at IS NOT NULL)
ORDER BY m.is_exact DESC, m.is_prefix DESC, m.level, char_length(m.name), lower(m.name), m.id
LIMIT $1::integer
`

type SearchPlacesParams struct {
	ResultLimit    int32
	ParentID       uuid.NullUUID
	Exact          string
	Prefix         string
	Contains       string
	Kind           pgtype.Text
	CandidateLimit int32
}

type SearchPlacesRow struct {
	ID        uuid.UUID
	Kind      string
	Name      string
	ParentID  uuid.NullUUID
	Timezone  string
	Source    string
	UserAdded bool
}

// Typeahead. Candidates are visible-by-row places whose lowercased name
// contains the pattern (served by the trigram index), restricted to the
// descendants of parent_id when it is set. Ranking: exact name, then name
// prefix, then substring; within each, broader kinds first (STATE before
// STORE), then shorter names, then name and id. The top candidate_limit
// candidates are then checked for a hidden ancestor, and the first
// result_limit survivors returned.
func (q *Queries) SearchPlaces(ctx context.Context, arg SearchPlacesParams) ([]SearchPlacesRow, error) {
	rows, err := q.db.Query(ctx, searchPlaces,
		arg.ResultLimit,
		arg.ParentID,
		arg.Exact,
		arg.Prefix,
		arg.Contains,
		arg.Kind,
		arg.CandidateLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchPlacesRow
	for rows.Next() {
		var i SearchPlacesRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.Name,
			&i.ParentID,
			&i.Timezone,
			&i.Source,
			&i.UserAdded,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const unfollowPlace = `-- name: UnfollowPlace :exec
DELETE FROM place_follows WHERE user_id = $1::uuid AND place_id = $2::uuid
`

type UnfollowPlaceParams struct {
	UserID  uuid.UUID
	PlaceID uuid.UUID
}

func (q *Queries) UnfollowPlace(ctx context.Context, arg UnfollowPlaceParams) error {
	_, err := q.db.Exec(ctx, unfollowPlace, arg.UserID, arg.PlaceID)
	return err
}
